// 🌍 GEODATA — geo.js, the Geography Path's picture data (PLAN_geography_path_2026-11-10.md §6 and §9 slice 0; her
//   "Yes, start slice 0" 2026-11-11). geo.js is GENERATED by tools/build_geo_js.py from Natural Earth (public domain) +
//   the drawings in tools/geo_runtime.js. Nothing in the app loads it yet (slice 1 adds HA_LAZY_FILES.geo); this test
//   pins what the later slices will lean on:
//   · every name the plan's appendices use has a picture: 7 continents, 5 oceans, 50 states, 87 countries, 12 rivers,
//     12 ranges, the Stage-3 "My country" features and all 59 Geography words (Appendix C), plus the real-example maps;
//   · every picture is a whole SVG (balanced tags, a viewBox, no NaN / undefined / null in it), small enough for a card,
//     and comes back as an SVG data URI the app's <img src> can show;
//   · outline / trace variants (the notebook's colouring and tracing pages) carry no fill;
//   · the Okabe–Ito colours, one credit line per picture, the file-size caps, no family or kid name anywhere, and the
//     same output every time (the build is deterministic, so a rebuild without a data change is a no-op diff).
//   run: node test_geo_data.js
const fs = require("fs"), path = require("path"), zlib = require("zlib"), vm = require("vm");
const file = path.join(__dirname, "geo.js");
const src = fs.readFileSync(file, "utf8");
let pass = 0, fail = 0;
const ok = (n, c, x) => { if (c) { pass++; console.log("  ok  - " + n); } else { fail++; console.log("  FAIL- " + n + (x !== undefined ? "  " + JSON.stringify(x).slice(0, 300) : "")); } };

// ── load it the browser's way (a classic script that sets window.HoweGeo) and the Node way (module.exports) ──
const win = {}; vm.runInNewContext(src, { window: win, module: undefined, console });
const G = require(file);
ok("loads as a classic script → window.HoweGeo, and as a Node module", !!(win.HoweGeo && G && G.svg && G.text && G.names && G.credit));
ok("version 1, public-domain credit lines present", G.version === 1 && /Natural Earth \(public domain\)/.test(G.credits["Natural Earth"].line) && /Howe Academy/.test(G.credits["Drawings"].line));

// ── the lists the plan names (Appendices A–E) ──
const CONTINENTS = ["North America", "South America", "Europe", "Asia", "Africa", "Australia", "Antarctica"];
const OCEANS = ["Pacific Ocean", "Atlantic Ocean", "Indian Ocean", "Arctic Ocean", "Southern Ocean"];
const STATES = ["Alabama", "Alaska", "Arizona", "Arkansas", "California", "Colorado", "Connecticut", "Delaware", "Florida", "Georgia", "Hawaii", "Idaho", "Illinois", "Indiana", "Iowa", "Kansas", "Kentucky", "Louisiana", "Maine", "Maryland", "Massachusetts", "Michigan", "Minnesota", "Mississippi", "Missouri", "Montana", "Nebraska", "Nevada", "New Hampshire", "New Jersey", "New Mexico", "New York", "North Carolina", "North Dakota", "Ohio", "Oklahoma", "Oregon", "Pennsylvania", "Rhode Island", "South Carolina", "South Dakota", "Tennessee", "Texas", "Utah", "Vermont", "Virginia", "Washington", "West Virginia", "Wisconsin", "Wyoming"];
const COUNTRIES = { "North America": ["Canada", "Mexico", "Cuba", "Guatemala", "Panama", "Costa Rica", "Jamaica", "Haiti", "Dominican Republic", "Honduras"],
  "South America": ["Brazil", "Argentina", "Chile", "Peru", "Colombia", "Venezuela", "Ecuador", "Bolivia", "Uruguay", "Paraguay"],
  "Europe": ["United Kingdom", "Ireland", "France", "Spain", "Portugal", "Italy", "Germany", "Netherlands", "Belgium", "Switzerland", "Austria", "Poland", "Czechia", "Hungary", "Greece", "Norway", "Sweden", "Finland", "Denmark", "Iceland", "Ukraine", "Russia", "Romania"],
  "Asia": ["China", "Japan", "South Korea", "North Korea", "India", "Pakistan", "Bangladesh", "Nepal", "Sri Lanka", "Vietnam", "Thailand", "Indonesia", "Philippines", "Malaysia", "Singapore", "Mongolia", "Kazakhstan", "Afghanistan", "Iran", "Iraq", "Saudi Arabia", "Israel", "Turkey", "United Arab Emirates"],
  "Africa": ["Egypt", "Morocco", "Algeria", "Libya", "Nigeria", "Ghana", "Ethiopia", "Kenya", "Tanzania", "Uganda", "Democratic Republic of the Congo", "South Africa", "Madagascar", "Sudan", "Somalia", "Senegal"],
  "Australia": ["Australia", "New Zealand", "Papua New Guinea", "Fiji"] };
const LINCOLN_BUILT_IN = ["United Kingdom", "France", "Germany", "Spain", "Italy", "Japan", "China", "India", "Brazil", "Australia", "Egypt", "South Africa", "Mexico", "Canada", "Russia", "South Korea", "Argentina", "Nigeria", "Saudi Arabia", "Turkey", "Greece", "Norway", "Thailand", "Kenya", "Colombia", "Peru", "Indonesia", "Pakistan", "Vietnam", "New Zealand"];
const RIVERS = ["Mississippi River", "Amazon River", "Nile River", "Congo River", "Danube River", "Rhine River", "Thames River", "Volga River", "Ganges River", "Yangtze River", "Mekong River", "Murray River"];
const RANGES = ["Appalachian Mountains", "Rocky Mountains", "Sierra Nevada", "Andes Mountains", "Alps", "Pyrenees", "Ural Mountains", "Caucasus Mountains", "Himalayas", "Atlas Mountains", "Drakensberg", "Great Dividing Range"];
const MY_COUNTRY = ["United States", "Washington DC", "Gulf of Mexico", "Great Lakes", "Mississippi River", "Rocky Mountains", "Appalachian Mountains", "Alaska", "Hawaii"];   // + Canada, Mexico (country cards), My state (a state card)
const WORDS = {   // Appendix C, by stage
  2: ["globe", "map", "equator", "North Pole", "South Pole", "Northern Hemisphere", "Southern Hemisphere", "compass rose", "map key", "north", "south", "east", "west"],
  3: ["continent", "ocean", "island", "lake", "river", "mountain", "desert", "coast", "bay", "peninsula"],
  4: ["cardinal directions", "intermediate directions", "lines of latitude", "lines of longitude", "prime meridian", "map scale", "elevation", "contour lines", "sea level", "time zone", "peak", "valley", "plain", "plateau"],
  6: ["isthmus", "archipelago", "delta", "strait", "gulf", "canyon", "tributaries", "glacier", "fjord", "oasis", "savanna", "rainforest", "atmosphere", "tectonic plates", "volcano", "caldera", "geyser", "precipitation", "evaporation", "biome", "tundra", "taiga"] };
const ALL_WORDS = [].concat(WORDS[2], WORDS[3], WORDS[4], WORDS[6]);
ok("Appendix C has 59 words (13 + 10 + 14 + 22)", ALL_WORDS.length === 59 && new Set(ALL_WORDS).size === 59);
const allCountries = [].concat.apply([], CONTINENTS.map(c => COUNTRIES[c] || []));
ok("Appendix B has 87 countries, every one of Lincoln's 30 built-in among them", allCountries.length === 87 && LINCOLN_BUILT_IN.every(n => allCountries.includes(n)), LINCOLN_BUILT_IN.filter(n => !allCountries.includes(n)));

// ── every picture: a whole SVG, a data URI, a sane size ──
function whole(t) {
  if (typeof t !== "string" || !/^<svg xmlns="http:\/\/www\.w3\.org\/2000\/svg" viewBox="[^"]+" width="\d+" height="\d+">/.test(t) || !t.endsWith("</svg>")) return "not an <svg …viewBox…>…</svg>";
  if (/NaN|undefined|null|Infinity/.test(t)) return "NaN/undefined/null in it";
  const opens = (t.match(/<(svg|g|path|circle|ellipse|rect|text)\b[^>]*(?<!\/)>/g) || []).length, closes = (t.match(/<\/(svg|g|path|circle|ellipse|rect|text)>/g) || []).length;
  if (opens !== closes) return "unbalanced tags " + opens + "/" + closes;
  const bad = (t.match(/ d="([^"]*)"/g) || []).find(d => !/^ d="[MLZACQHVmlzacqhv0-9 .,\-]*"$/.test(d));   // maps use M/L/Z; the drawings add arcs and curves
  if (bad) return "odd path data " + bad.slice(0, 40);
  return "";
}
function check(kind, names, o, cap) {
  const bad = [], big = [];
  names.forEach(n => { const t = G.text(kind, n, o); const w = t ? whole(t) : "no picture"; if (w) bad.push(n + ": " + w); else if (t.length > (cap || 90000)) big.push(n + ": " + t.length); });   // the Asia card (silhouette + inset) is the biggest, ~72 KB
  return { bad, big };
}
let r = check("continent", CONTINENTS); ok("7 continent cards: silhouette + globe inset, whole SVGs", !r.bad.length && !r.big.length, r.bad.concat(r.big));
r = check("ocean", OCEANS); ok("5 ocean cards: the world map with the ocean lit", !r.bad.length && !r.big.length, r.bad.concat(r.big));
r = check("state", STATES, { region: "Southeast", capital: true }); ok("50 state cards: outline + US inset", !r.bad.length && !r.big.length, r.bad.concat(r.big));
r = check("country", allCountries); ok("87 country cards: the country lit on its continent", !r.bad.length && !r.big.length, r.bad.concat(r.big));
ok("a country card dots its capital (Paris, Tokyo, Nairobi) and Singapore keeps its speck", ["France", "Japan", "Kenya"].every(n => /<circle[^>]*fill="#111827"/.test(G.text("country", n))) && !!G.text("country", "Singapore"));
r = check("feature", RIVERS.concat(RANGES)); ok("12 rivers + 12 ranges lit on their continent (Appendix E)", !r.bad.length && !r.big.length, r.bad.concat(r.big));
r = check("us", MY_COUNTRY); ok("Stage-3 My Country features on the US map", !r.bad.length && !r.big.length, r.bad.concat(r.big));
r = check("word", ALL_WORDS); ok("59 Geography words: a drawing or a diagram each", !r.bad.length && !r.big.length, r.bad.concat(r.big));
const realWords = ALL_WORDS.filter(n => G.text("word", n, { real: true }) !== G.text("word", n));
r = check("word", realWords, { real: true }); ok("real-example maps for the landform words (lake → the Great Lakes, peninsula → Florida, isthmus → Panama…), " + realWords.length + " of them", realWords.length >= 18 && !r.bad.length, r.bad);
ok("the real example differs from the drawing for the words that have both", ["lake", "peninsula", "isthmus", "delta", "strait", "canyon", "desert", "plateau"].every(n => realWords.includes(n)), realWords);
ok("tributaries has only the map (the Missouri and Ohio into the Mississippi) — the same picture either way", G.text("word", "tributaries", { real: true }) === G.text("word", "tributaries") && /stroke="#f97316"/.test(G.text("word", "tributaries")));
ok("every picture comes back as an SVG data URI (what <img src> shows)", [["continent", "Africa"], ["state", "North Carolina"], ["country", "France"], ["word", "equator"]].every(([k, n]) => /^data:image\/svg\+xml;utf8,%3Csvg/.test(G.uri(k, n) || "") && G.svg(k, n) === G.uri(k, n)));
ok("a name the data lacks → null, never a broken picture", G.text("country", "Atlantis") === null && G.uri("state", "Puerto Rico") === null && G.text("word", "xyzzy") === null);

// ── outline / trace variants for the notebook ──
const outl = G.text("continent", "Africa", { outline: true }), trace = G.text("state", "North Carolina", { outline: true, trace: true });
ok("outline: the big shape has no fill and a dark stroke (the inset keeps its colour as the find-it hint); trace: dashed", /<g transform="translate[^"]*"><path d="[^"]*" fill="none" stroke="#1f2937"/.test(outl) && /<g transform="translate[^"]*"><path d="[^"]*" fill="none" stroke="#1f2937"[^>]*stroke-dasharray=/.test(trace));
ok("the silhouette of a continent is ONE shape (edge under, fill over — no seams between its countries)", (G.text("continent", "North America").match(/<path /g) || []).length >= 2 && /fill="#E69F00" /.test(G.text("continent", "North America")));

// ── colours and credits ──
ok("Okabe–Ito continent colours (colour-blind safe) and the five region colours", G.colors.cont["North America"] === "#E69F00" && G.colors.cont.Africa === "#009E73" && Object.keys(G.colors.region).join() === "Northeast,Southeast,Midwest,Southwest,West");
ok("a state card takes its region's colour", /fill="#0072B2"/.test(G.text("state", "Maine", { region: "Northeast" })) && /fill="#E69F00"/.test(G.text("state", "North Carolina", { region: "Southeast" })));
ok("credit per kind: maps → Natural Earth; a drawn word → Howe Academy", /Natural Earth/.test(G.credit("state", "Ohio")) && /Natural Earth/.test(G.credit("country", "Peru")) && /Howe Academy/.test(G.credit("word", "volcano")));
ok("names(): the plan's lists, in the plan's order", JSON.stringify(G.names("continent")) === JSON.stringify(CONTINENTS) && JSON.stringify(G.names("ocean")) === JSON.stringify(OCEANS) && JSON.stringify(G.names("state")) === JSON.stringify(STATES) && JSON.stringify(G.names("country")) === JSON.stringify(allCountries) && JSON.stringify(G.names("river")) === JSON.stringify(RIVERS) && JSON.stringify(G.names("range")) === JSON.stringify(RANGES));
ok("names('word') covers every Appendix-C word", ALL_WORDS.every(w => G.names("word").includes(w)), ALL_WORDS.filter(w => !G.names("word").includes(w)));

// ── the file itself ──
const gz = zlib.gzipSync(src).length;
console.log("  geo.js " + (src.length / 1024).toFixed(0) + " KB raw · " + (gz / 1024).toFixed(0) + " KB gzip");
ok("under the caps: 600 KB raw, 200 KB gzip (lazy, loaded only by a family with the unit)", src.length < 600 * 1024 && gz < 200 * 1024, [src.length, gz]);
ok("generated header names the build and the licence; the build and runtime are in tools/", /GENERATED by tools\/build_geo_js\.py/.test(src.slice(0, 400)) && /Natural Earth \(public domain\)/.test(src.slice(0, 600)) && fs.existsSync(path.join(__dirname, "tools", "build_geo_js.py")) && fs.existsSync(path.join(__dirname, "tools", "geo_runtime.js")));
const names = /\b(howe academy|adrienne|andrew|julian|lincoln|ellis|lucy|sara|caleb|taylor|kenzie|dewalt|burris|melanie|david)\b/i;
const noCredit = src.replace(/Howe Academy/g, "");
ok("no family or kid names in the file (the credit line aside)", !names.test(noCredit), (noCredit.match(names) || [])[0]);
ok("deterministic: the same picture text twice", G.text("country", "Brazil") === G.text("country", "Brazil") && G.text("word", "delta") === G.text("word", "delta"));
ok("the runtime never touches the DOM or the app (no document / db / masteryData / fetch in it)", !/\b(document\.|db\.|masteryData|unitStudies|fetch\(|XMLHttpRequest|localStorage)/.test(src.slice(src.indexOf("const G = GEO_DATA"))));

console.log("\n" + pass + " passed, " + fail + " failed");
process.exit(fail ? 1 : 0);
